-- ---------------------------------------------------------------------------
-- Stockgap Fuels Limited - enterprise platform
-- Migration 001: core schema
--
-- Engine: SQLite (WAL, foreign keys enforced per connection). The schema is
-- written in portable SQL so it maps 1:1 onto PostgreSQL; see
-- docs/database/schema.md for the PostgreSQL translation notes.
--
-- Conventions
--   * ids            TEXT, UUID v4 generated by the application
--   * money          INTEGER, Nigerian kobo (1 NGN = 100 kobo)
--   * quantities     REAL, 3 decimal places (MT / litres / units)
--   * timestamps     TEXT, ISO-8601 UTC
-- ---------------------------------------------------------------------------

PRAGMA foreign_keys = ON;

-- ------------------------------------------------------------------ identity
CREATE TABLE roles (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL UNIQUE,
  label       TEXT NOT NULL,
  description TEXT NOT NULL,
  is_system   INTEGER NOT NULL DEFAULT 1 CHECK (is_system IN (0, 1))
);

CREATE TABLE permissions (
  code        TEXT PRIMARY KEY,
  module      TEXT NOT NULL,
  description TEXT NOT NULL
);

CREATE TABLE role_permissions (
  role_id         TEXT NOT NULL REFERENCES roles (id) ON DELETE CASCADE,
  permission_code TEXT NOT NULL REFERENCES permissions (code) ON DELETE CASCADE,
  PRIMARY KEY (role_id, permission_code)
);

CREATE TABLE parties (
  id                TEXT PRIMARY KEY,
  code              TEXT NOT NULL UNIQUE,
  name              TEXT NOT NULL,
  type              TEXT NOT NULL CHECK (type IN ('supplier', 'distributor', 'retailer', 'customer', 'transporter')),
  contact_name      TEXT,
  email             TEXT,
  phone             TEXT,
  address           TEXT,
  city              TEXT,
  state             TEXT,
  tin               TEXT,
  status            TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'on_hold', 'inactive')),
  credit_limit_kobo INTEGER NOT NULL DEFAULT 0 CHECK (credit_limit_kobo >= 0),
  notes             TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);

CREATE TABLE users (
  id                   TEXT PRIMARY KEY,
  email                TEXT NOT NULL UNIQUE,
  full_name            TEXT NOT NULL,
  password_hash        TEXT NOT NULL,
  role_id              TEXT NOT NULL REFERENCES roles (id),
  party_id             TEXT REFERENCES parties (id),
  phone                TEXT,
  job_title            TEXT,
  status               TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
  must_change_password INTEGER NOT NULL DEFAULT 0 CHECK (must_change_password IN (0, 1)),
  last_login_at        TEXT,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL
);

CREATE INDEX users_role_idx ON users (role_id);
CREATE INDEX users_party_idx ON users (party_id);

CREATE TABLE sessions (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  ip         TEXT,
  user_agent TEXT,
  created_at TEXT NOT NULL
);

CREATE INDEX sessions_user_idx ON sessions (user_id);
CREATE INDEX sessions_expiry_idx ON sessions (expires_at);

CREATE TABLE password_resets (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  used_at    TEXT,
  created_at TEXT NOT NULL
);

-- ------------------------------------------------------- facilities & catalogue
CREATE TABLE locations (
  id         TEXT PRIMARY KEY,
  code       TEXT NOT NULL UNIQUE,
  name       TEXT NOT NULL,
  type       TEXT NOT NULL CHECK (type IN ('terminal', 'depot', 'warehouse', 'plant', 'retail_outlet')),
  city       TEXT NOT NULL,
  state      TEXT NOT NULL,
  address    TEXT,
  capacity_note TEXT,
  is_active  INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1))
);

CREATE TABLE products (
  id              TEXT PRIMARY KEY,
  sku             TEXT NOT NULL UNIQUE,
  name            TEXT NOT NULL,
  category        TEXT NOT NULL CHECK (category IN ('lpg', 'petroleum', 'cylinder', 'component')),
  unit            TEXT NOT NULL CHECK (unit IN ('MT', 'L', 'UNIT', 'KG')),
  pack_size       TEXT,
  description     TEXT,
  reorder_level   REAL NOT NULL DEFAULT 0 CHECK (reorder_level >= 0),
  unit_price_kobo INTEGER NOT NULL DEFAULT 0 CHECK (unit_price_kobo >= 0),
  status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'discontinued')),
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);

CREATE TABLE inventory (
  id          TEXT PRIMARY KEY,
  location_id TEXT NOT NULL REFERENCES locations (id),
  product_id  TEXT NOT NULL REFERENCES products (id),
  quantity    REAL NOT NULL DEFAULT 0 CHECK (quantity >= -0.0005),
  reserved    REAL NOT NULL DEFAULT 0 CHECK (reserved >= 0),
  updated_at  TEXT NOT NULL,
  UNIQUE (location_id, product_id)
);

CREATE INDEX inventory_product_idx ON inventory (product_id);

CREATE TABLE inventory_movements (
  id             TEXT PRIMARY KEY,
  location_id    TEXT NOT NULL REFERENCES locations (id),
  product_id     TEXT NOT NULL REFERENCES products (id),
  direction      TEXT NOT NULL CHECK (direction IN ('in', 'out')),
  quantity       REAL NOT NULL CHECK (quantity > 0),
  balance_after  REAL NOT NULL,
  reason         TEXT NOT NULL CHECK (reason IN (
                    'opening_balance', 'goods_receipt', 'production_input',
                    'production_output', 'dispatch', 'adjustment',
                    'quality_rejection', 'transfer_in', 'transfer_out')),
  reference_type TEXT,
  reference_id   TEXT,
  note           TEXT,
  created_by     TEXT REFERENCES users (id),
  created_at     TEXT NOT NULL
);

CREATE INDEX movements_product_idx ON inventory_movements (product_id, created_at);
CREATE INDEX movements_reference_idx ON inventory_movements (reference_type, reference_id);

-- ---------------------------------------------------------------- procurement
CREATE TABLE purchase_orders (
  id             TEXT PRIMARY KEY,
  reference      TEXT NOT NULL UNIQUE,
  supplier_id    TEXT NOT NULL REFERENCES parties (id),
  location_id    TEXT NOT NULL REFERENCES locations (id),
  status         TEXT NOT NULL DEFAULT 'draft' CHECK (status IN (
                   'draft', 'pending_approval', 'approved', 'partially_received',
                   'received', 'cancelled')),
  currency       TEXT NOT NULL DEFAULT 'NGN',
  total_kobo     INTEGER NOT NULL DEFAULT 0 CHECK (total_kobo >= 0),
  expected_date  TEXT,
  notes          TEXT,
  requested_by   TEXT NOT NULL REFERENCES users (id),
  approved_by    TEXT REFERENCES users (id),
  approved_at    TEXT,
  created_at     TEXT NOT NULL,
  updated_at     TEXT NOT NULL
);

CREATE INDEX po_supplier_idx ON purchase_orders (supplier_id);
CREATE INDEX po_status_idx ON purchase_orders (status);

CREATE TABLE purchase_order_lines (
  id                TEXT PRIMARY KEY,
  purchase_order_id TEXT NOT NULL REFERENCES purchase_orders (id) ON DELETE CASCADE,
  product_id        TEXT NOT NULL REFERENCES products (id),
  quantity          REAL NOT NULL CHECK (quantity > 0),
  received_quantity REAL NOT NULL DEFAULT 0 CHECK (received_quantity >= 0),
  unit_price_kobo   INTEGER NOT NULL CHECK (unit_price_kobo >= 0)
);

CREATE INDEX po_lines_po_idx ON purchase_order_lines (purchase_order_id);

CREATE TABLE goods_receipts (
  id                TEXT PRIMARY KEY,
  reference         TEXT NOT NULL UNIQUE,
  purchase_order_id TEXT NOT NULL REFERENCES purchase_orders (id),
  location_id       TEXT NOT NULL REFERENCES locations (id),
  received_by       TEXT NOT NULL REFERENCES users (id),
  received_at       TEXT NOT NULL,
  notes             TEXT,
  created_at        TEXT NOT NULL
);

CREATE TABLE goods_receipt_lines (
  id                    TEXT PRIMARY KEY,
  goods_receipt_id      TEXT NOT NULL REFERENCES goods_receipts (id) ON DELETE CASCADE,
  purchase_order_line_id TEXT NOT NULL REFERENCES purchase_order_lines (id),
  product_id            TEXT NOT NULL REFERENCES products (id),
  quantity              REAL NOT NULL CHECK (quantity > 0)
);

CREATE INDEX gr_lines_receipt_idx ON goods_receipt_lines (goods_receipt_id);

-- --------------------------------------------------------------- manufacturing
CREATE TABLE bill_of_materials (
  id                   TEXT PRIMARY KEY,
  product_id           TEXT NOT NULL REFERENCES products (id),
  component_product_id TEXT NOT NULL REFERENCES products (id),
  quantity_per_unit    REAL NOT NULL CHECK (quantity_per_unit > 0),
  UNIQUE (product_id, component_product_id)
);

CREATE TABLE production_orders (
  id                TEXT PRIMARY KEY,
  reference         TEXT NOT NULL UNIQUE,
  type              TEXT NOT NULL CHECK (type IN ('cylinder_manufacture', 'lpg_filling')),
  product_id        TEXT NOT NULL REFERENCES products (id),
  location_id       TEXT NOT NULL REFERENCES locations (id),
  planned_quantity  REAL NOT NULL CHECK (planned_quantity > 0),
  produced_quantity REAL NOT NULL DEFAULT 0,
  status            TEXT NOT NULL DEFAULT 'planned' CHECK (status IN (
                      'planned', 'in_progress', 'awaiting_quality', 'completed',
                      'rejected', 'cancelled')),
  due_date          TEXT,
  started_at        TEXT,
  completed_at      TEXT,
  created_by        TEXT NOT NULL REFERENCES users (id),
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);

CREATE INDEX production_status_idx ON production_orders (status);

CREATE TABLE production_consumptions (
  id                   TEXT PRIMARY KEY,
  production_order_id  TEXT NOT NULL REFERENCES production_orders (id) ON DELETE CASCADE,
  component_product_id TEXT NOT NULL REFERENCES products (id),
  quantity             REAL NOT NULL CHECK (quantity > 0),
  created_at           TEXT NOT NULL
);

CREATE INDEX consumption_order_idx ON production_consumptions (production_order_id);

-- -------------------------------------------------------------------- quality
CREATE TABLE quality_inspections (
  id                 TEXT PRIMARY KEY,
  reference          TEXT NOT NULL UNIQUE,
  production_order_id TEXT REFERENCES production_orders (id),
  inspection_type    TEXT NOT NULL CHECK (inspection_type IN (
                       'finished_goods', 'incoming_material', 'cylinder_certification', 'safety_audit')),
  checked_quantity   REAL NOT NULL CHECK (checked_quantity >= 0),
  passed_quantity    REAL NOT NULL CHECK (passed_quantity >= 0),
  failed_quantity    REAL NOT NULL CHECK (failed_quantity >= 0),
  result             TEXT NOT NULL CHECK (result IN ('pass', 'fail', 'conditional')),
  notes              TEXT,
  inspector_id       TEXT NOT NULL REFERENCES users (id),
  inspected_at       TEXT NOT NULL,
  created_at         TEXT NOT NULL
);

CREATE INDEX inspection_production_idx ON quality_inspections (production_order_id);

-- ---------------------------------------------------------------------- sales
CREATE TABLE customer_orders (
  id                     TEXT PRIMARY KEY,
  reference              TEXT NOT NULL UNIQUE,
  customer_id            TEXT NOT NULL REFERENCES parties (id),
  location_id            TEXT NOT NULL REFERENCES locations (id),
  status                 TEXT NOT NULL DEFAULT 'draft' CHECK (status IN (
                           'draft', 'pending_approval', 'approved', 'allocated',
                           'dispatched', 'delivered', 'cancelled')),
  channel                TEXT NOT NULL CHECK (channel IN ('distributor', 'retailer', 'consumer', 'corporate')),
  total_kobo             INTEGER NOT NULL DEFAULT 0 CHECK (total_kobo >= 0),
  requested_delivery_date TEXT,
  delivery_address       TEXT,
  contact_phone          TEXT,
  notes                  TEXT,
  created_by             TEXT NOT NULL REFERENCES users (id),
  approved_by            TEXT REFERENCES users (id),
  approved_at            TEXT,
  created_at             TEXT NOT NULL,
  updated_at             TEXT NOT NULL
);

CREATE INDEX orders_customer_idx ON customer_orders (customer_id);
CREATE INDEX orders_status_idx ON customer_orders (status);

CREATE TABLE customer_order_lines (
  id                 TEXT PRIMARY KEY,
  customer_order_id  TEXT NOT NULL REFERENCES customer_orders (id) ON DELETE CASCADE,
  product_id         TEXT NOT NULL REFERENCES products (id),
  quantity           REAL NOT NULL CHECK (quantity > 0),
  allocated_quantity REAL NOT NULL DEFAULT 0 CHECK (allocated_quantity >= 0),
  unit_price_kobo    INTEGER NOT NULL CHECK (unit_price_kobo >= 0)
);

CREATE INDEX order_lines_order_idx ON customer_order_lines (customer_order_id);

-- ------------------------------------------------------------------ logistics
CREATE TABLE shipments (
  id             TEXT PRIMARY KEY,
  reference      TEXT NOT NULL UNIQUE,
  order_id       TEXT NOT NULL REFERENCES customer_orders (id),
  transporter_id TEXT REFERENCES parties (id),
  vehicle_plate  TEXT,
  driver_name    TEXT,
  driver_phone   TEXT,
  destination    TEXT NOT NULL,
  status         TEXT NOT NULL DEFAULT 'planned' CHECK (status IN (
                    'planned', 'loaded', 'in_transit', 'delivered', 'failed')),
  dispatched_at  TEXT,
  delivered_at   TEXT,
  delivery_notes TEXT,
  confirmed_by   TEXT REFERENCES users (id),
  created_by     TEXT NOT NULL REFERENCES users (id),
  created_at     TEXT NOT NULL,
  updated_at     TEXT NOT NULL
);

CREATE INDEX shipments_order_idx ON shipments (order_id);
CREATE INDEX shipments_transporter_idx ON shipments (transporter_id);

-- -------------------------------------------------------------------- finance
CREATE TABLE invoices (
  id              TEXT PRIMARY KEY,
  reference       TEXT NOT NULL UNIQUE,
  order_id        TEXT NOT NULL REFERENCES customer_orders (id),
  customer_id     TEXT NOT NULL REFERENCES parties (id),
  amount_kobo     INTEGER NOT NULL CHECK (amount_kobo >= 0),
  amount_paid_kobo INTEGER NOT NULL DEFAULT 0 CHECK (amount_paid_kobo >= 0),
  status          TEXT NOT NULL DEFAULT 'issued' CHECK (status IN (
                     'issued', 'partially_paid', 'paid', 'void')),
  issued_at       TEXT NOT NULL,
  due_date        TEXT,
  created_at      TEXT NOT NULL
);

CREATE INDEX invoices_customer_idx ON invoices (customer_id);

CREATE TABLE payments (
  id            TEXT PRIMARY KEY,
  reference     TEXT NOT NULL UNIQUE,
  invoice_id    TEXT NOT NULL REFERENCES invoices (id),
  amount_kobo   INTEGER NOT NULL CHECK (amount_kobo > 0),
  method        TEXT NOT NULL CHECK (method IN ('bank_transfer', 'cheque', 'cash', 'pos')),
  received_at   TEXT NOT NULL,
  notes         TEXT,
  recorded_by   TEXT NOT NULL REFERENCES users (id),
  created_at    TEXT NOT NULL
);

CREATE INDEX payments_invoice_idx ON payments (invoice_id);

-- ------------------------------------------------------------------------ HSE
CREATE TABLE hse_incidents (
  id                TEXT PRIMARY KEY,
  reference         TEXT NOT NULL UNIQUE,
  location_id       TEXT NOT NULL REFERENCES locations (id),
  category          TEXT NOT NULL CHECK (category IN (
                      'near_miss', 'first_aid', 'equipment_failure', 'spill',
                      'fire', 'vehicle', 'security', 'other')),
  severity          TEXT NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  description       TEXT NOT NULL,
  occurred_at       TEXT NOT NULL,
  reported_by       TEXT NOT NULL REFERENCES users (id),
  status            TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'investigating', 'closed')),
  corrective_action TEXT,
  closed_at         TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);

CREATE INDEX hse_status_idx ON hse_incidents (status);

-- ----------------------------------------------------- notifications & audit
CREATE TABLE notifications (
  id         TEXT PRIMARY KEY,
  user_id    TEXT REFERENCES users (id) ON DELETE CASCADE,
  role_id    TEXT REFERENCES roles (id) ON DELETE CASCADE,
  title      TEXT NOT NULL,
  body       TEXT NOT NULL,
  level      TEXT NOT NULL DEFAULT 'info' CHECK (level IN ('info', 'success', 'warning', 'critical')),
  link       TEXT,
  read_at    TEXT,
  created_at TEXT NOT NULL
);

CREATE INDEX notifications_user_idx ON notifications (user_id, read_at);
CREATE INDEX notifications_role_idx ON notifications (role_id, read_at);

-- Role-addressed notifications are shared, so each recipient tracks its own read
-- state here without duplicating the notification row.
CREATE TABLE notification_reads (
  notification_id TEXT NOT NULL REFERENCES notifications (id) ON DELETE CASCADE,
  user_id         TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  read_at         TEXT NOT NULL,
  PRIMARY KEY (notification_id, user_id)
);

CREATE TABLE audit_logs (
  id          TEXT PRIMARY KEY,
  actor_id    TEXT,
  actor_name  TEXT,
  action      TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id   TEXT,
  summary     TEXT NOT NULL,
  metadata    TEXT,
  ip          TEXT,
  created_at  TEXT NOT NULL
);

CREATE INDEX audit_entity_idx ON audit_logs (entity_type, entity_id);
CREATE INDEX audit_created_idx ON audit_logs (created_at);

-- ------------------------------------------------------- marketing & settings
CREATE TABLE enquiries (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  company    TEXT,
  email      TEXT NOT NULL,
  phone      TEXT,
  subject    TEXT NOT NULL,
  message    TEXT NOT NULL,
  type       TEXT NOT NULL CHECK (type IN ('general', 'business', 'supplier', 'customer')),
  status     TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'in_review', 'responded', 'closed')),
  created_at TEXT NOT NULL
);

CREATE TABLE settings (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE sequences (
  key   TEXT PRIMARY KEY,
  value INTEGER NOT NULL
);
